class LRUCache:
    """A class that implements an LRU (Least Recently Used) cache using a hash map for O(1) access
    and a fixed-size list to manage the order of usage.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.access_order = []

    def get(self, key: int) -> int:
        """Return the value of the key if present in the cache, else return -1."""
        if key in self.cache:
            self.access_order.remove(key)
            self.access_order.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        """Insert or update the value of the key, maintaining the LRU order."""
        if key in self.cache:
            self.cache[key] = value
            self.access_order.remove(key)
        else:
            if len(self.cache) >= self.capacity:
                oldest_key = self.access_order.pop(0)
                del self.cache[oldest_key]
            self.cache[key] = value
        self.access_order.append(key)
